import heapq
from collections import Counter


def dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    features = set(data.get("features", []))
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    domains = []
    for name in names:
        values = list(rows[name])
        values.append(None)
        domains.append(values)
    best, best_key = None, None
    for values in product(*domains):
        chosen = dict(zip(names, values))
        valid = True
        for name, bounds in roots.items():
            version = chosen[name]
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        edges = {name: [] for name in names if chosen[name] is not None}
        for name, version in chosen.items():
            if version is None:
                continue
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                valid = False
                break
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = chosen[dep["name"]]
                if target is None or not dep["min"] <= target <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue
        # The installed set must be exactly the roots' active dependency closure.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if any(chosen[name] is not None for name in names if name not in reachable):
            continue
        if any(chosen[name] is None for name in reachable):
            continue
        # Reject cycles, including self loops.
        state = {}
        def visit(node):
            if state.get(node) == 1:
                return False
            if state.get(node) == 2:
                return True
            state[node] = 1
            for child in edges[node]:
                if not visit(child):
                    return False
            state[node] = 2
            return True
        if not all(visit(node) for node in edges):
            continue
        key = tuple(-1 if chosen[name] is None else chosen[name] for name in names)
        if best is None or (key > best_key if maximize else key < best_key):
            best, best_key = chosen, key
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: best[name] for name in names if best[name] is not None}}


def c01(d): return dependency_solver(d, "descending", True)
def c02(d): return dependency_solver(d, "descending", False)
def c03(d): return dependency_solver(d, "ascending", True)
def c04(d): return dependency_solver(d, "ascending", False)
def c05(d): return dependency_solver(d, "descending", True)


def c06(data):
    events = data["events"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(events):
        if event.get("sequence", 0) > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"
    def rounded(n, d=10000):
        return (n + d // 2) // d if half_up else n // d
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def c07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    for subset in combinations([j for j in jobs if j["id"] not in blocked], k):
        ids = [j["id"] for j in subset]
        idset = set(ids)
        if not mandatory.issubset(idset):
            continue
        counts = Counter(j["group"] for j in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        active = []
        compatible = True
        for job in ordered:
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                compatible = False
                break
        if not compatible:
            continue
        value = sum(j["value"] for j in subset)
        selected = sorted(ids)
        if (best_ids is None or value > best_value or
                (value == best_value and selected > best_ids)):
            best_ids, best_value = selected, value
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def c08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    start_mask = bit.get(source, 0)
    start_state = (source, start_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, start_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == target and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


